// seed: tests/seed.spec.ts (гость) · прод, только чтение: не-GET обрываются, SW выключен.
import { test, expect } from '@playwright/test';
import { prepareReadOnly, LOAD } from './ssr-infra.helpers';

test.use({ serviceWorkers: 'block' });

declare global {
  interface Window { __qaSpaMarker?: number }
}

test.describe('SSR/SSG — браузер с JS', () => {
  test('SPA-навигация главная → поиск → карточка → назад без перезагрузки #be4863 @desktop @prod-safe', async ({ page, context }) => {
    await prepareReadOnly(context);
    const pageErrors: string[] = [];
    page.on('pageerror', (e) => pageErrors.push(e.message));
    let documents = 0;
    page.on('request', (r) => { if (r.resourceType() === 'document' && r.frame() === page.mainFrame()) documents++; });

    await page.goto('/');
    const allListings = page.getByRole('link', { name: 'צפה בכל העסקים' }).first();
    await expect(allListings).toBeVisible(LOAD);
    await page.evaluate(() => { window.__qaSpaMarker = 1; });

    await allListings.click();
    await page.waitForURL(/\/search(\?|$)/);
    const card = page.locator('main a[href^="/businessdetail?id="]').first();
    await expect(card).toBeVisible(LOAD);

    await card.click();
    await page.waitForURL(/\/businessdetail\?id=/);

    await page.goBack();
    await page.waitForURL(/\/search(\?|$)/);
    await expect(page.locator('main a[href^="/businessdetail?id="]').first()).toBeVisible(LOAD);

    expect(await page.evaluate(() => window.__qaSpaMarker), 'метка window сохранилась — без перезагрузки').toBe(1);
    expect(await page.evaluate(() => performance.getEntriesByType('navigation').length), 'одна навигация документа').toBe(1);
    expect(documents, 'запросов типа document за весь путь').toBe(1);
    expect(pageErrors, 'pageerror').toEqual([]);
  });
});
